struct Receiver { seen: Mutex<HashSet<String>> }

impl Receiver {
    fn claim(&self, key: &str) -> bool {
        // true => newly inserted => we won; false => duplicate
        self.seen.lock().unwrap().insert(key.to_owned())
    }
    fn on_message(&self, msg: Message) -> Result<()> {
        if !self.claim(&msg.key) { return ack(msg); }   // duplicate: absorb
        apply_effects(&msg)?; ack(msg)
    }
}

